const proton = new THREE.Group();
const pDisc = new THREE.Mesh(new THREE.CircleGeometry(0.165, 40),
  new THREE.MeshBasicMaterial({ color: 0x16466E, depthTest: false }));
const pRing = new THREE.Mesh(new THREE.RingGeometry(0.165, 0.195, 40),
  new THREE.MeshBasicMaterial({ color: 0x4A7FB5, depthTest: false }));
const barMat = new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false });
const barH = new THREE.Mesh(new THREE.PlaneGeometry(0.175, 0.040), barMat);
const barV = new THREE.Mesh(new THREE.PlaneGeometry(0.040, 0.175), barMat);
