// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
   sphere silhouette  → LineLoop unit circle, billboarded, scale R   #B0B0B0
   equatorial ellipse → LineLoop unit circle in XZ plane, scale R    #CFCFCF
   pick shell         → Mesh SphereGeometry(1) opacity 0 (raycast target)
   proton             → Group(billboard): CircleGeometry(.16) #16466E
                        + RingGeometry(.16,.19) #4A7FB5 + 2 white PlaneGeometry bars '+'
   electron           → Mesh SphereGeometry(.10) #7FB3D5 + billboard ring outline
   e- grab handle     → Mesh SphereGeometry(.30) invisible
   meridian arc       → Line, slerp(northPole → eDir)*R, 48 pts      #2E86AB
   r segment          → Line proton→electron, black
   F arrow            → Group[ CylinderGeometry shaft + ConeGeometry head ] #A92E22
   polar dashed axis  → Line + LineDashedMaterial, (0,0,0)→(0,R+0.4,0) black
   equatorial dashed  → Line + LineDashedMaterial along Z axis, black
   drop guide         → dashed electron→foot on XZ plane            #9FC8E0
   radial guide       → dashed centre→foot in XZ plane              #9FC8E0
   labels             → addLabel italic serif 'r' and 'F'
 ─────────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;
const UP = new THREE.Vector3(0, 1, 0);
const R0 = 2.0;                 // shell radius at r = 1 a0

let sep   = 1.0;                // separation in Bohr radii
let eAzim = -10 * DEG;          // electron azimuth about +Y from +X
let eElev =  42 * DEG;          // electron elevation above equator

/* ── helpers ─────────────────────────────────────────────────────────── */
function circleXY(n) {
  const p = [];
  for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; p.push(new THREE.Vector3(Math.cos(a), Math.sin(a), 0)); }
  return p;
}
function circleXZ(n) {
  const p = [];
  for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; p.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a))); }
  return p;
}
function mkLine(pts, color, width) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = new THREE.LineBasicMaterial({ color, linewidth: width || 1 });
  return new THREE.Line(g, m);
}
function mkDashed(pts, color, dash, gap, opacity) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = new THREE.LineDashedMaterial({
    color, dashSize: dash, gapSize: gap,
    transparent: (opacity !== undefined && opacity < 1), opacity: opacity === undefined ? 1 : opacity
  });
  const l = new THREE.Line(g, m);
  l.computeLineDistances();
  return l;
}
function setPts(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
function slerpVec(a, b, t) {
  const dot = THREE.MathUtils.clamp(a.dot(b), -1, 1);
  const th = Math.acos(dot);
  if (th < 1e-4) return a.clone();
  const s = Math.sin(th);
  return a.clone().multiplyScalar(Math.sin((1 - t) * th) / s)
    .add(b.clone().multiplyScalar(Math.sin(t * th) / s));
}
const billboards = [];

/* ── sphere silhouette (always faces camera) ─────────────────────────── */
const silhouette = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(circleXY(160)),
  new THREE.LineBasicMaterial({ color: 0xB0B0B0 })
);
silhouette.frustumCulled = false;
scene.add(silhouette); billboards.push(silhouette);

/* ── equatorial circle in the XZ plane ───────────────────────────────── */
const equator = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(circleXZ(160)),
  new THREE.LineBasicMaterial({ color: 0xCFCFCF })
);
scene.add(equator);

/* faint translucent shell body + invisible raycast target */
const pickSphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 40, 28),
  new THREE.MeshBasicMaterial({ color: 0xBFD6E8, transparent: true, opacity: 0.045, depthWrite: false, side: THREE.DoubleSide })
);
scene.add(pickSphere);

/* ── dashed guides ───────────────────────────────────────────────────── */
const vertDash = mkDashed([new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, R0 + 0.4, 0)], 0x222222, 0.12, 0.10);
const zDash    = mkDashed([new THREE.Vector3(0, 0, R0 + 0.3), new THREE.Vector3(0, 0, -R0 - 0.3)], 0x222222, 0.12, 0.10);
const dropDash = mkDashed([new THREE.Vector3(), new THREE.Vector3()], 0x9FC8E0, 0.10, 0.09);
const radDash  = mkDashed([new THREE.Vector3(), new THREE.Vector3()], 0x9FC8E0, 0.10, 0.09);
[vertDash, zDash, dropDash, radDash].forEach(l => { l.renderOrder = 0; scene.add(l); });

/* ── meridian arc ────────────────────────────────────────────────────── */
const meridian = mkLine([new THREE.Vector3(), new THREE.Vector3()], 0x2E86AB);
meridian.renderOrder = 2;
scene.add(meridian);

/* ── r segment ───────────────────────────────────────────────────────── */
const rLine = mkLine([new THREE.Vector3(), new THREE.Vector3()], 0x000000);
rLine.material.depthTest = false; rLine.renderOrder = 3;
scene.add(rLine);

/* ── F arrow (shaft + head, built along +Y) ──────────────────────────── */
const redMat  = new THREE.MeshBasicMaterial({ color: 0xA92E22, depthTest: false });
const shaftG  = new THREE.CylinderGeometry(0.048, 0.048, 1, 16); shaftG.translate(0, 0.5, 0);
const headG   = new THREE.ConeGeometry(0.125, 0.32, 22);         headG.translate(0, 0.16, 0);
const shaft   = new THREE.Mesh(shaftG, redMat);
const head    = new THREE.Mesh(headG, redMat);
const arrow   = new THREE.Group();
arrow.add(shaft); arrow.add(head);
arrow.renderOrder = 5; shaft.renderOrder = 5; head.renderOrder = 5;
scene.add(arrow);

/* ── proton (billboarded disc with white '+') ────────────────────────── */
const proton = new THREE.Group();
const pDisc = new THREE.Mesh(new THREE.CircleGeometry(0.165, 40),
  new THREE.MeshBasicMaterial({ color: 0x16466E, depthTest: false }));
const pRing = new THREE.Mesh(new THREE.RingGeometry(0.165, 0.195, 40),
  new THREE.MeshBasicMaterial({ color: 0x4A7FB5, depthTest: false }));
const barMat = new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false });
const barH = new THREE.Mesh(new THREE.PlaneGeometry(0.175, 0.040), barMat);
const barV = new THREE.Mesh(new THREE.PlaneGeometry(0.040, 0.175), barMat);
pDisc.position.z = 0.001; pRing.position.z = 0.001; barH.position.z = 0.004; barV.position.z = 0.004;
proton.add(pDisc, pRing, barH, barV);
proton.renderOrder = 7;
proton.traverse(o => { o.renderOrder = 7; o.frustumCulled = false; });
scene.add(proton); billboards.push(proton);

/* ── electron ────────────────────────────────────────────────────────── */
const electron = new THREE.Mesh(new THREE.SphereGeometry(0.10, 28, 20),
  new THREE.MeshBasicMaterial({ color: 0x7FB3D5, depthTest: false }));
electron.renderOrder = 8;
scene.add(electron);
const eRing = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(circleXY(48).map(p => p.multiplyScalar(0.105))),
  new THREE.LineBasicMaterial({ color: 0x3E7CA6, depthTest: false })
);
eRing.renderOrder = 9; eRing.frustumCulled = false;
scene.add(eRing); billboards.push(eRing);

const eHandle = new THREE.Mesh(new THREE.SphereGeometry(0.30, 12, 10),
  new THREE.MeshBasicMaterial({ visible: false }));
scene.add(eHandle);

/* ── billboard update (runs every frame, before the draw) ────────────── */
scene.onBeforeRender = function (rnd, scn, cam) {
  for (const o of billboards) { o.quaternion.copy(cam.quaternion); o.updateMatrixWorld(true); }
};

/* ── main update ─────────────────────────────────────────────────────── */
let rLabel = null, fLabel = null;
const readoutEl = document.getElementById('readout');
const sepValEl  = document.getElementById('sepVal');

function sci(x, d) {
  const e = Math.floor(Math.log10(Math.abs(x)));
  return (x / Math.pow(10, e)).toFixed(d === undefined ? 2 : d) + '&times;10<sup>' + e + '</sup>';
}

function update() {
  const R = R0 * Math.pow(sep, 0.35);
  const eDir = new THREE.Vector3(
    Math.cos(eElev) * Math.cos(eAzim),
    Math.sin(eElev),
    Math.cos(eElev) * Math.sin(eAzim)
  );
  const eP = eDir.clone().multiplyScalar(R);

  silhouette.scale.setScalar(R);
  equator.scale.setScalar(R);
  pickSphere.scale.setScalar(R);

  electron.position.copy(eP);
  eRing.position.copy(eP);
  eHandle.position.copy(eP);

  /* meridian arc: north pole → electron along its own great circle */
  const arcPts = [];
  for (let i = 0; i <= 48; i++) arcPts.push(slerpVec(UP, eDir, i / 48).multiplyScalar(R));
  setPts(meridian, arcPts);

  /* r segment */
  setPts(rLine, [new THREE.Vector3(0, 0, 0), eP]);

  /* F arrow: length ∝ 1/r², tail at the electron, head pointing at the proton */
  const Lraw = 1.1 / (sep * sep);
  const L = Math.min(Lraw, 2.6);
  const headMin = 0.15 * R;
  const hPos = Math.max(headMin, R - L);      // head tip distance from centre
  const tail = hPos + L;                      // tail distance from centre
  arrow.position.copy(eDir).multiplyScalar(tail);
  arrow.quaternion.setFromUnitVectors(UP, eDir.clone().negate());
  const hLen = Math.min(0.32, 0.42 * L);
  head.scale.set(1, hLen / 0.32, 1);
  head.position.y = L - hLen;
  shaft.scale.set(1, Math.max(0.002, L - hLen * 0.8), 1);

  /* dashed guides */
  setPts(vertDash, [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, R + 0.4, 0)]);
  setPts(zDash,    [new THREE.Vector3(0, 0, R + 0.3), new THREE.Vector3(0, 0, -R - 0.3)]);
  const foot = new THREE.Vector3(eP.x, 0, eP.z);
  setPts(dropDash, [eP, foot]);
  setPts(radDash,  [new THREE.Vector3(0, 0, 0), foot]);

  /* labels */
  if (rLabel) rLabel.pos.copy(eDir).multiplyScalar(R * 0.60);
  if (fLabel) fLabel.pos.copy(eDir).multiplyScalar(hPos + Math.min(L, R) * 0.45);

  /* readout */
  const rm = sep * 5.29e-11;
  const F  = 8.99e9 * Math.pow(1.602e-19, 2) / (rm * rm);
  sepValEl.textContent = sep.toFixed(2);
  readoutEl.innerHTML =
    'r = ' + sci(rm) + ' m<br>' +
    'F = k e²/r² = <b>' + sci(F) + ' N</b><br>' +
    'F / F(a<sub>0</sub>) = ' + (1 / (sep * sep)).toFixed(2) + '&times;' +
    (Lraw > 2.6 ? '<br><span style="color:#A92E22">arrow clipped to fit</span>' : '');
}

update();

/* ── camera (after all geometry) ─────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 12, z: 12 },   // shallow view: wide flat equatorial ellipse
  rollDeg: 0,
  heightFraction: 0.62
});
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────── */
rLabel = addLabel('<i>r</i>', new THREE.Vector3(), { fontSize: '17px', offset: [-15, -13] });
rLabel.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
fLabel = addLabel('<i>F</i>', new THREE.Vector3(), { fontSize: '17px', offset: [16, 16] });
fLabel.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
addLabel('proton (+)', new THREE.Vector3(0, -0.34, 0), { fontSize: '10px', color: '#16466E', offset: [-26, 8] });
update();

/* ── hover / click explanations ──────────────────────────────────────── */
registerInteractive(electron, {
  title: 'The electron',
  tooltip: 'Drag me anywhere on the shell',
  body: 'The electron sits on a spherical shell of radius r around the proton. Drag it: no matter where it goes, the force arrow F keeps pointing straight back at the nucleus — that is what "central force" means.'
});
registerInteractive(pDisc, {
  title: 'The proton (nucleus)',
  tooltip: 'Proton: charge +e at the centre',
  body: 'A single proton of charge +e = 1.602×10⁻¹⁹ C sits at the centre. It attracts the electron with F = k e²/r², k = 8.99×10⁹ N·m²/C².'
});
registerInteractive(shaft, {
  title: 'Coulomb force F',
  tooltip: 'F = k e² / r² — attractive, along r',
  body: 'F is drawn antiparallel to r: it points from the electron back toward the proton, so the interaction is attractive. Its length scales as 1/r², so halving r quadruples F. At r = a₀ = 5.29×10⁻¹¹ m, F ≈ 8.25×10⁻⁸ N.'
});

/* ── drag the electron over the shell ────────────────────────────────── */
const _rc = new THREE.Raycaster();
const _pt = new THREE.Vector2();
let dragging = false;

function toPointer(e) {
  const r = canvas.getBoundingClientRect();
  _pt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (e) => {
  toPointer(e);
  _rc.setFromCamera(_pt, camera);
  if (_rc.intersectObject(eHandle, false).length) {
    dragging = true;
    sweeping = false;
    controls.enabled = false;
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
  }
}, true);
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  toPointer(e);
  _rc.setFromCamera(_pt, camera);
  const hits = _rc.intersectObject(pickSphere, false);
  if (hits.length) {
    const p = hits[0].point.clone().normalize();
    eAzim = Math.atan2(p.z, p.x);
    eElev = THREE.MathUtils.clamp(Math.asin(THREE.MathUtils.clamp(p.y, -1, 1)), -82 * DEG, 82 * DEG);
    update();
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

/* ── UI wiring ───────────────────────────────────────────────────────── */
const sepInput = document.getElementById('sep');
sepInput.addEventListener('input', () => {
  anim = null; sweeping = false;
  sep = parseFloat(sepInput.value);
  update();
});

document.getElementById('showGuides').addEventListener('change', (e) => {
  const v = e.target.checked;
  vertDash.visible = zDash.visible = dropDash.visible = radDash.visible = v;
});

document.getElementById('resetElectron').addEventListener('click', () => {
  anim = null; sweeping = false;
  eAzim = -10 * DEG; eElev = 42 * DEG;
  update();
});

/* ── demo steps ──────────────────────────────────────────────────────── */
const steps = [
  { title: 'Ground state, as drawn',
    narration: 'The proton sits at the centre of the sphere and the electron rides on the shell at the most probable distance, one Bohr radius away. The black segment r and the red arrow F lie along the same line, but F points inward.',
    sep: 1, az: -10 * DEG, el: 42 * DEG, sweep: false },
  { title: 'Move the electron around the shell',
    narration: 'The electron is sweeping around the shell. The meridian arc, the dashed drop lines, r and F all follow — F never stops pointing at the proton, because the Coulomb force is central. Try dragging it yourself.',
    sep: 1, az: -10 * DEG, el: 30 * DEG, sweep: true },
  { title: 'Pull the electron farther out',
    narration: 'At r = 2a₀ the direction of F is unchanged but the arrow shrinks to one quarter of its length: F = k e²/r².',
    sep: 2, az: -10 * DEG, el: 42 * DEG, sweep: false },
  { title: 'Squeeze it closer',
    narration: 'At r = 0.5a₀ the arrow grows four times longer — the attraction climbs steeply as the electron approaches the nucleus.',
    sep: 0.5, az: -10 * DEG, el: 42 * DEG, sweep: false }
];
let stepIdx = 0;
let sweeping = false;
let anim = null;

function tweenTo(tSep, tAz, tEl, dur, after) {
  const s0 = sep, a0 = eAzim, e0 = eElev, t0 = performance.now();
  let dAz = tAz - a0;
  while (dAz > Math.PI) dAz -= 2 * Math.PI;
  while (dAz < -Math.PI) dAz += 2 * Math.PI;
  anim = function () {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const u = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    sep = s0 + (tSep - s0) * u;
    eAzim = a0 + dAz * u;
    eElev = e0 + (tEl - e0) * u;
    sepInput.value = sep;
    update();
    if (k >= 1) { anim = null; if (after) after(); }
  };
}

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const st = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.narration;
  sweeping = false;
  tweenTo(st.sep, st.az, st.el, 750, () => { sweeping = !!st.sweep; });
}

document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

let playTimer = null;
document.getElementById('playAll').addEventListener('click', () => {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('playAll').textContent = '▶ Play demo'; return; }
  document.getElementById('playAll').textContent = '■ Stop';
  let k = 0;
  goToStep(0);
  playTimer = setInterval(() => {
    k++;
    if (k >= steps.length) { clearInterval(playTimer); playTimer = null; document.getElementById('playAll').textContent = '▶ Play demo'; return; }
    goToStep(k);
  }, 4200);
});

/* ── own animation loop for tweens / sweep ───────────────────────────── */
(function loop() {
  requestAnimationFrame(loop);
  if (anim) anim();
  else if (sweeping) { eAzim += 0.011; update(); }
})();

goToStep(0);
// @FIGURE_CODE_END

